INSERT INTO
    dex.moves (slug, name, external_id, generation_introduced_id, effect)
SELECT
    m.slug,
    m.name,
    m.external_id,
    gen.id,
    m.effect
FROM
    m
    JOIN meta.generations gen ON gen.slug = m.generation_introduced_slug ON CONFLICT (slug) DO NOTHING;